  1→import { useCallback, useRef, useState, type DragEvent } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import { useConfig } from '../hooks/useConfig';
  4→import './FileUpload.css';
  5→
  6→interface FileUploadProps {
  7→  onUpload: (files: File[]) => Promise<void>;
  8→  onLoadSample: () => Promise<void>;
  9→}
 10→
 11→export function FileUpload({ onUpload, onLoadSample }: FileUploadProps) {
 12→  const { t } = useTranslation();
 13→  const { maxTotalSizeBytes } = useConfig();
 14→  const [dragging, setDragging] = useState(false);
 15→  const [uploading, setUploading] = useState(false);
 16→  const [loadingSample, setLoadingSample] = useState(false);
 17→  const inputRef = useRef<HTMLInputElement>(null);
 18→
 19→  const handleFiles = useCallback(async (fileList: FileList) => {
 20→    const files = Array.from(fileList);
 21→    const nonCsv = files.filter(f => !f.name.toLowerCase().endsWith('.csv'));
 22→    if (nonCsv.length > 0) {
 23→      alert(t('csvOnly'));
 24→      return;
 25→    }
 26→    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 27→    if (totalSize > maxTotalSizeBytes) {
 28→      alert(t('fileTooLarge', { maxSize: `${maxTotalSizeBytes / (1024 * 1024)}MB` }));
 29→      return;
 30→    }
 31→    setUploading(true);
 32→    try {
 33→      await onUpload(files);
 34→    } finally {
 35→      setUploading(false);
 36→    }
 37→  }, [onUpload, t, maxTotalSizeBytes]);
 38→
 39→  const handleLoadSample = useCallback(async () => {
 40→    setLoadingSample(true);
 41→    try {
 42→      await onLoadSample();
 43→    } finally {
 44→      setLoadingSample(false);
 45→    }
 46→  }, [onLoadSample]);
 47→
 48→  const onDrop = useCallback((e: DragEvent) => {
 49→    e.preventDefault();
 50→    setDragging(false);
 51→    if (e.dataTransfer.files.length > 0) handleFiles(e.dataTransfer.files);
 52→  }, [handleFiles]);
 53→
 54→  const onDragOver = useCallback((e: DragEvent) => {
 55→    e.preventDefault();
 56→    setDragging(true);
 57→  }, []);
 58→
 59→  const onDragLeave = useCallback(() => {
 60→    setDragging(false);
 61→  }, []);
 62→
 63→  return (
 64→    <div className="file-upload-wrapper">
 65→      <div
 66→        className={`file-upload ${dragging ? 'file-upload--dragging' : ''}`}
 67→        onDrop={onDrop}
 68→        onDragOver={onDragOver}
 69→        onDragLeave={onDragLeave}
 70→        onClick={() => inputRef.current?.click()}
 71→      >
 72→        <input
 73→          ref={inputRef}
 74→          type="file"
 75→          accept=".csv"
 76→          multiple
 77→          className="file-upload__input"
 78→          onChange={(e) => {
 79→            if (e.target.files && e.target.files.length > 0) handleFiles(e.target.files);
 80→            e.target.value = '';
 81→          }}
 82→        />
 83→        {uploading ? (
 84→          <p className="file-upload__text">{t('uploading')}</p>
 85→        ) : (
 86→          <p className="file-upload__text">
 87→            {t('uploadDropText', { maxSize: `${maxTotalSizeBytes / (1024 * 1024)}MB` })}
 88→          </p>
 89→        )}
 90→      </div>
 91→      <div className="file-upload-divider">
 92→        <span>{t('uploadOr')}</span>
 93→      </div>
 94→      <button
 95→        className="file-upload-sample-btn"
 96→        onClick={handleLoadSample}
 97→        disabled={loadingSample}
 98→      >
 99→        {loadingSample ? t('loading') : t('loadSample')}
100→      </button>
101→    </div>
102→  );
103→}
