  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 16→import './App.css';
 17→
 18→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 19→  const { theme, toggleTheme } = useTheme();
 20→  const { language, setLanguage, t } = useTranslation();
 21→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 22→  const [error, setError] = useState<string | null>(null);
 23→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 24→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 25→  );
 26→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 27→  const [agentOpen, setAgentOpen] = useState(true);
 28→
 29→  useEffect(() => {
 30→    document.title = t('appTitle');
 31→  }, [t]);
 32→
 33→  useEffect(() => {
 34→    if (tables.length === 0) {
 35→      setQueryResult(null);
 36→      setError(null);
 37→      setEditorQuery(undefined);
 38→    }
 39→  }, [tables]);
 40→
 41→  const handleAgentToggle = () => {
 42→    setAgentOpen((prev) => !prev);
 43→  };
 44→
 45→  const handleLoadSample = useCallback(async () => {
 46→    setError(null);
 47→    try {
 48→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 49→      if (!response.ok) throw new Error('Failed to load sample dataset');
 50→      await refreshTables();
 51→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 52→    } catch (e) {
 53→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 54→    }
 55→  }, [refreshTables]);
 56→
 57→  const handleFileUpload = useCallback(
 58→    async (files: File[]) => {
 59→      setError(null);
 60→      let lastName = '';
 61→      try {
 62→        for (const file of files) {
 63→          const formData = new FormData();
 64→          formData.append('file', file);
 65→          const response = await fetch('/api/upload', {
 66→            method: 'POST',
 67→            body: formData,
 68→          });
 69→          if (!response.ok) throw new Error('Failed to upload file');
 70→          const result = await response.json();
 71→          lastName = result.name;
 72→        }
 73→        await refreshTables();
 74→        if (lastName) {
 75→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
 76→        }
 77→      } catch (e) {
 78→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 79→      }
 80→    },
 81→    [refreshTables]
 82→  );
 83→
 84→  const handleQueryExecute = useCallback(
 85→    async (sql: string) => {
 86→      setError(null);
 87→      setQueryResult(null);
 88→      try {
 89→        const start = performance.now();
 90→        const response = await fetch('/api/query', {
 91→          method: 'POST',
 92→          headers: { 'Content-Type': 'application/json' },
 93→          body: JSON.stringify({ sql }),
 94→        });
 95→        const elapsed = performance.now() - start;
 96→
 97→        if (!response.ok) {
 98→          const errorData = await response.json();
 99→          throw new Error(errorData.detail || 'Query execution failed');
100→        }
101→
102→        const result = await response.json();
103→        setQueryResult({
104→          columns: result.columns,
105→          rows: result.rows,
106→          rowCount: result.rowCount,
107→          executionTimeMs: elapsed,
108→          resultType: result.resultType,
109→        });
110→        await refreshTables();
111→      } catch (e) {
112→        setError(e instanceof Error ? e.message : 'Query execution failed');
113→      }
114→    },
115→    [refreshTables]
116→  );
117→
118→  const handleTableClick = useCallback((tableName: string) => {
119→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
120→  }, []);
121→
122→  const handleTableDelete = useCallback(async (tableName: string) => {
123→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
124→    try {
125→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
126→        method: 'DELETE',
127→      });
128→      if (!response.ok) throw new Error('Failed to delete table');
129→      await refreshTables();
130→    } catch (e) {
131→      setError(e instanceof Error ? e.message : 'Failed to delete table');
132→    }
133→  }, [refreshTables, t]);
134→
135→  const appClass = [
136→    'app',
137→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
138→  ].filter(Boolean).join(' ');
139→
140→  const themeIcon = theme === 'dark' ? (
141→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
142→      <circle cx="12" cy="12" r="5" />
143→      <line x1="12" y1="1" x2="12" y2="3" />
144→      <line x1="12" y1="21" x2="12" y2="23" />
145→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
146→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
147→      <line x1="1" y1="12" x2="3" y2="12" />
148→      <line x1="21" y1="12" x2="23" y2="12" />
149→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
150→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
151→    </svg>
152→  ) : (
153→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
154→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
155→    </svg>
156→  );
157→
158→  return (
159→    <div className={appClass}>
160→      <div className="app__sidebar-wrapper">
161→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
162→      </div>
163→      {agentOpen ? (
164→        <div className="app__agent-wrapper">
165→          <div className="app__header">
166→            <h1 className="app__title">{t('appTitle')}</h1>
167→            <div className="app__header-actions">
168→              <button
169→                className="app__lang-toggle"
170→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
171→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
172→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
173→              >
174→                {language === 'en' ? 'EN' : '中'}
175→              </button>
176→              <button
177→                className="app__theme-toggle"
178→                onClick={toggleTheme}
179→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
180→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
181→              >
182→                {themeIcon}
183→              </button>
184→              <button
185→                className="app__agent-toggle app__agent-toggle--active"
186→                onClick={handleAgentToggle}
187→              >
188→                {t('editorMode')}
189→              </button>
190→            </div>
191→          </div>
192→          <AgentPanel
193→            langfuseStatus={langfuseStatus}
194→            tables={tables}
195→            onUpload={handleFileUpload}
196→            onLoadSample={handleLoadSample}
197→          />
198→        </div>
199→      ) : (
200→        <div className="app__editor-wrapper">
201→          <div className="app__header">
202→            <h1 className="app__title">{t('appTitle')}</h1>
203→            <div className="app__header-actions">
204→              <button
205→                className="app__lang-toggle"
206→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
207→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
208→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
209→              >
210→                {language === 'en' ? 'EN' : '中'}
211→              </button>
212→              <button
213→                className="app__theme-toggle"
214→                onClick={toggleTheme}
215→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
216→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
217→              >
218→                {themeIcon}
219→              </button>
220→              <button
221→                className="app__agent-toggle"
222→                onClick={handleAgentToggle}
223→              >
224→                {t('agentMode')}
225→              </button>
226→            </div>
227→          </div>
228→          <div className="app__mode-header">
229→            <span className="app__mode-title">{t('editorMode')}</span>
230→          </div>
231→          <main className="app__main">
232→            {tables.length === 0 ? (
233→              <div className="app__empty">
234→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
235→              </div>
236→            ) : (
237→              <>
238→                <QueryEditor
239→                  onExecute={handleQueryExecute}
240→                  initialQuery={editorQuery}
241→                />
242→                {error && (
243→                  <ErrorMessage message={error} onDismiss={() => setError(null)} />
244→                )}
245→                {queryResult?.resultType === 'markdown' ? (
246→                  <ResultMarkdown result={queryResult} />
247→                ) : (
248→                  <ResultsTable result={queryResult} />
249→                )}
250→              </>
251→            )}
252→          </main>
253→        </div>
254→      )}
255→    </div>
256→  );
257→}
258→
259→export default function App() {
260→  const [tables, setTables] = useState<TableInfo[]>([]);
261→  const [loading, setLoading] = useState(true);
262→  const [error, setError] = useState<string | null>(null);
263→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
264→
265→  const refreshTables = useCallback(async () => {
266→    try {
267→      const response = await fetch('/api/tables');
268→      if (!response.ok) throw new Error('Failed to fetch tables');
269→      const data = await response.json();
270→      setTables(data);
271→    } catch (e) {
272→      console.error('Failed to refresh tables:', e);
273→    }
274→  }, []);
275→
276→  useEffect(() => {
277→    (async () => {
278→      try {
279→        const response = await fetch('/api/health');
280→        if (!response.ok) throw new Error('Backend is not available');
281→        await refreshTables();
282→        try {
283→          const lfRes = await fetch('/api/langfuse/status');
284→          if (lfRes.ok) {
285→            setLangfuseStatus(await lfRes.json());
286→          }
287→        } catch {
288→          // Langfuse status fetch is non-critical
289→        }
290→      } catch (e) {
291→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
292→      } finally {
293→        setLoading(false);
294→      }
295→    })();
296→  }, [refreshTables]);
297→
298→  if (loading) {
299→    return <div className="app-loading">Connecting to backend...</div>;
300→  }
301→
302→  if (error) {
303→    return (
304→      <div className="app-error">Failed to connect: {error}</div>
305→    );
306→  }
307→
308→  return (
309→    <ConfigProvider>
310→      <LanguageProvider>
311→        <ThemeProvider>
312→          <AgentProvider refreshTables={refreshTables}>
313→            <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
314→          </AgentProvider>
315→        </ThemeProvider>
316→      </LanguageProvider>
317→    </ConfigProvider>
318→  );
319→}
