 1→import { useState, useEffect, type ReactNode } from 'react';
 2→import { ConfigContext, DEFAULT_MAX_TOTAL_SIZE_BYTES } from '../hooks/useConfig';
 3→
 4→export function ConfigProvider({ children }: { children: ReactNode }) {
 5→  const [maxTotalSizeBytes, setMaxTotalSizeBytes] = useState(DEFAULT_MAX_TOTAL_SIZE_BYTES);
 6→
 7→  useEffect(() => {
 8→    (async () => {
 9→      try {
10→        const res = await fetch('/api/config');
11→        if (res.ok) {
12→          const data = await res.json();
13→          if (typeof data.maxTotalSizeBytes === 'number') {
14→            setMaxTotalSizeBytes(data.maxTotalSizeBytes);
15→          }
16→        }
17→      } catch {
18→        // Config fetch is non-critical; use default
19→      }
20→    })();
21→  }, []);
22→
23→  return (
24→    <ConfigContext.Provider value={{ maxTotalSizeBytes }}>
25→      {children}
26→    </ConfigContext.Provider>
27→  );
28→}
