 1→import { createContext, useContext } from 'react';
 2→
 3→interface ConfigContextValue {
 4→  maxTotalSizeBytes: number;
 5→}
 6→
 7→export const DEFAULT_MAX_TOTAL_SIZE_BYTES = 500 * 1024 * 1024; // 500MB
 8→
 9→export const ConfigContext = createContext<ConfigContextValue>({
10→  maxTotalSizeBytes: DEFAULT_MAX_TOTAL_SIZE_BYTES,
11→});
12→
13→export function useConfig() {
14→  return useContext(ConfigContext);
15→}
