17→export function AgentPanel({ langfuseStatus, tables, onUpload, onLoadSample }: AgentPanelProps) {
18→  const { t } = useTranslation();
19→  const { messages, clearMessages } = useAgent();
20→  const bottomRef = useRef<HTMLDivElement>(null);
